    [SerializeField] private float _attackRange = 2f;
    [SerializeField] private float _followSpeed = 3f;
    [Tooltip("离玩家超过此距离时直接传送到身边，防止掉队")]
    [SerializeField] private float _maxTeleportDistance = 12f;

    private Transform _player;
    private EnemyCore _core;
    private EnemyMovement _movement;
    private EnemySkillManager _skillManager;
    private bool _isActive;

    // 进化倾向 buff：记录原始属性，动态刷新时从原始值重算
    private float _origMaxHealth, _origPatrolSpeed, _origChaseSpeed;
    private float _origDetectionRange, _origAttackRange, _origContactDamage, _origContactDamageCooldown;

    /// <summary>所有活跃随从列表（供 MapManager 查询，避免 FindObjectsByType）</summary>
    public static readonly System.Collections.Generic.List<EnemyFollower> ActiveFollowers = new();

    // ── 道具增强（静态，影响所有随从）──
    /// <summary>随从生命上限乘区（免疫球蛋白）</summary>
    public static float MaxHealthMultiplier = 1f;
    /// <summary>随从伤害乘区（集落刺激因子 CSF）</summary>
    public static float DamageMultiplier = 1f;
    /// <summary>随从技能冷却乘区（白细胞介素-2 IL-2）</summary>
    public static float FollowerCooldownFactor = 1f;
    /// <summary>随从攻击是否附带减速（干扰素）</summary>
    public static bool ApplySlow = false;
    /// <summary>减速比例（干扰素），0.8 = 减速20%</summary>
    public static float SlowFactor = 0.8f;
    /// <summary>减速持续时间（秒）</summary>
    public static float SlowDuration = 2f;
    /// <summary>随从数量上限（胸腺肽），默认4</summary>
    public static int MaxFollowerCount = 4;

    private void OnEnable()
    {
        ActiveFollowers.Add(this);

        if (MapManager.Instance != null)
            MapManager.Instance.OnRoomSwitchStarted += OnRoomSwitchStarted;
    }

    private void OnDisable()
    {
        ActiveFollowers.Remove(this);
        if (_core != null && _core.Health != null)
            _core.Health.OnDied -= HandleDeath;
        if (MapManager.Instance != null)
            MapManager.Instance.OnRoomSwitchStarted -= OnRoomSwitchStarted;
    }

    private void Awake()
    {
        _core = GetComponent<EnemyCore>();
    }

    /// <summary>
    /// 激活随从模式。
    /// </summary>
    public void Activate(Transform player)
    {
        _player = player;
        _isActive = true;

        _movement = _core.Movement;
        _skillManager = _core.SkillManager;

        // 记录原始属性，用于进化倾向 buff 重算
        if (_core.Health != null)
        {
            _origMaxHealth = _core.Health.MaxHealth;
            _origPatrolSpeed = _core.Health.PatrolSpeed;
            _origChaseSpeed = _core.Health.ChaseSpeed;
            _origDetectionRange = _core.Health.DetectionRange;
            _origAttackRange = _core.Health.AttackRange;
            _origContactDamage = _core.Health.ContactDamage;
            _origContactDamageCooldown = _core.Health.ContactDamageCooldown;

            // 应用当前进化倾向 buff
            ApplyEvolutionBuff();

            _core.Health.OnDied += HandleDeath;
        }
    }

    /// <summary>根据玩家进化倾向刷新随从全属性增幅（叠加道具乘区）</summary>
    public void ApplyEvolutionBuff()
    {
        if (_core?.Health == null || !_isActive) return;

        var playerStats = _player?.GetComponent<PlayerStats>();
        if (playerStats == null) return;

        float tendency = playerStats.EvolutionTendency;
        float factor = playerStats.EvolveFollowerBuffFactor;
        float mult = Mathf.Max(0f, 1f + (-tendency) * factor);

        _core.Health.MaxHealth = Mathf.Max(_origMaxHealth * mult * MaxHealthMultiplier, 1f);
        _core.Health.PatrolSpeed = _origPatrolSpeed * mult;
        _core.Health.ChaseSpeed = _origChaseSpeed * mult;
        _core.Health.DetectionRange = _origDetectionRange * mult;
        _core.Health.AttackRange = _origAttackRange * mult;
        _core.Health.ContactDamage = _origContactDamage * mult * DamageMultiplier;
        _core.Health.ContactDamageCooldown = _origContactDamageCooldown * mult;

        // 应用随从技能冷却乘区
        if (_skillManager != null)
        {
            foreach (var s in _skillManager.SkillInstances)
                s.CooldownFactor = FollowerCooldownFactor;
        }
    }

    /// <summary>刷新所有活跃随从的进化倾向 buff（由 PlayerStats 在倾向值变化时调用）</summary>
    public static void RefreshAllFollowers(float tendency, float factor)
    {
        foreach (var f in ActiveFollowers)
            f.ApplyEvolutionBuff();
    }

    /// <summary>刷新所有活跃随从（道具增强变化时调用）</summary>
    public static void RefreshAllFollowers()
    {
        foreach (var f in ActiveFollowers)
            f.ApplyEvolutionBuff();
    }

    private void Update()
    {
        if (!_isActive || _player == null) return;
        if (_core.Health != null && _core.Health.IsDead) return;

        Vector2 pos = transform.position;
        Vector2 playerPos = _player.position;

        // 离玩家过远 → 直接传送到身边，防止掉队或被卡住
        float sqrDistToPlayer = (pos - playerPos).sqrMagnitude;
        if (sqrDistToPlayer > _maxTeleportDistance * _maxTeleportDistance)
        {
            _movement?.Teleport(playerPos);
            return;
        }

        // 寻找最近的敌人
        Transform nearestEnemy = FindNearestEnemy(pos);

        if (nearestEnemy != null)
        {
            Vector2 enemyPos = nearestEnemy.position;
            float distToEnemy = Vector2.Distance(pos, enemyPos);

            if (distToEnemy <= _attackRange)
            {
                _movement?.Stop();

                // 尝试释放技能
                if (_skillManager != null && _skillManager.SkillInstances.Count > 0)
                {
                    Vector2 dir = (enemyPos - pos).normalized;
                    _skillManager.TryCastSkill(0, _core, dir);
                }
            }
            else
            {
                _movement?.MoveTowardsPosition(enemyPos, _followSpeed);
            }
            return;
        }

        // 没有敌人 → 跟随玩家
        float distToPlayer = Vector2.Distance(pos, playerPos);
        if (distToPlayer > _followDistance)
        {
            _movement?.MoveTowardsPosition(playerPos, _followSpeed);
        }
        else
        {
            _movement?.Stop();
        }
    }

    private Transform FindNearestEnemy(Vector2 center)
    {
        Collider2D[] hits = Physics2D.OverlapCircleAll(center, _detectionRange);
        Transform nearest = null;
        float minDist = float.MaxValue;

        foreach (var hit in hits)
        {
            if (!hit.CompareTag("Enemy")) continue;
            if (_player != null && hit.transform == _player) continue;

            float d = (hit.transform.position - (Vector3)center).sqrMagnitude;
            if (d < minDist)
            {
                minDist = d;
                nearest = hit.transform;
            }
        }

        return nearest;
    }

    private void OnRoomSwitchStarted(int fromRoomId, int toRoomId)
    {
        if (!_isActive || _player == null) return;

        // 1. 将随从切换到新房间的父节点，防止旧房间禁用时连带禁用它
        if (MapManager.Instance != null)
        {
            RoomRoot targetRoom = MapManager.Instance.GetRoom(toRoomId);
            if (targetRoom != null)
                transform.SetParent(targetRoom.transform, true);
        }

        // 2. 立即传送到玩家身边
        _movement?.Teleport(_player.position);
    }

    private void HandleDeath()
    {
        _isActive = false;

        // 禁用碰撞
        foreach (var col in GetComponentsInChildren<Collider2D>())
            col.enabled = false;

        _movement?.Stop();
        Destroy(gameObject, 0.5f);
    }
}

using System;
using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 敌人聚合门面：实现 IEnemy / IDamageable / ISkillCaster，自动收集子组件并负责连线。
/// 碰撞伤害直接在此处理（OnTriggerStay2D + OnCollisionStay2D）。
/// 所有数值属性来源：EnemyStats（类似 PlayerStats 的单一数据源）。
/// </summary>
[DisallowMultipleComponent]
public class EnemyCore : MonoBehaviour, IEnemy
{
    [Header("配置")]
    public EnemyConfig config;

    [Header("动画（可选，留空则从 config displayName 自动查找）")]
    [Tooltip("AnimatorController 资产路径（Assets/ 开始），留空则按敌人名自动查找")]
    [SerializeField] private string _animatorControllerPath = "";

    // 子组件
    public EnemyStats Health { get; private set; }
    public EnemyMovement Movement { get; private set; }
    public EnemySkillManager SkillManager { get; private set; }
    public EnemyStateMachine StateMachine { get; private set; }

    // 缓存玩家引用 + 最后已知位置（供状态机读取）
    public Transform PlayerTarget { get; set; }
    public Vector2 LastKnownPlayerPosition { get; set; }

    public Transform EnemyTransform => transform;
    public bool IsDead => Health != null && Health.IsDead;
    public bool IsAssimilated { get; private set; }
    public IReadOnlyList<SkillInstance> SkillInstances =>
        SkillManager != null ? SkillManager.SkillInstances : new List<SkillInstance>();
    public event Action OnDied;
    public event Action<IEnemy> OnAssimilated;

    /// <summary>全局静态事件 — 任意敌人死亡时触发 (EnemyCore)</summary>
    public static event Action<EnemyCore> OnAnyEnemyDied;

    /// <summary>全局静态事件 — 任意敌人接触伤害命中时触发 (enemy, hitTarget)</summary>
    public static event Action<EnemyCore, GameObject> OnAnyContactHit;

    /// <summary>玩家碰撞伤害减免乘区（细胞骨架），1=正常，0.7=减免30%</summary>
    public static float PlayerCollisionReductionFactor = 1f;

    // 碰撞伤害冷却
    private float _lastContactDamageTime = -10f;
    private Animator _animator;
    private SpriteRenderer _spriteRenderer;

    private void Awake()
    {
        Health       = GetComponent<EnemyStats>();
        Movement     = GetComponent<EnemyMovement>();
        SkillManager = GetComponent<EnemySkillManager>();
        StateMachine = GetComponent<EnemyStateMachine>();

        if (Health       == null) Health       = gameObject.AddComponent<EnemyStats>();
        if (Movement     == null) Movement     = gameObject.AddComponent<EnemyMovement>();
        if (SkillManager == null) SkillManager = gameObject.AddComponent<EnemySkillManager>();
        if (StateMachine == null) StateMachine = gameObject.AddComponent<EnemyStateMachine>();

        _animator = GetComponent<Animator>();
        _spriteRenderer = GetComponent<SpriteRenderer>();

        // 运行时 fallback：若 Animator 缺少 controller，按敌人名自动加载
        if (_animator != null && _animator.runtimeAnimatorController == null && config != null)
        {
            string enemyName = config.displayName;
            string autoPath = "Assets/Animations/Enemy/" + enemyName + "/" + enemyName + "_Controller.controller";
#if UNITY_EDITOR
            var ctrl = UnityEditor.AssetDatabase.LoadAssetAtPath<RuntimeAnimatorController>(autoPath);
            if (ctrl != null)
            {
                _animator.runtimeAnimatorController = ctrl;
            }
            else
            {
                Debug.LogWarning("[EnemyCore] AnimatorController not found at: " + autoPath);
            }
#else
            // 非 Editor 环境需将 controller 放入 Resources 文件夹
            var ctrl = Resources.Load<RuntimeAnimatorController>(enemyName + "_Controller");
            if (ctrl != null)
                _animator.runtimeAnimatorController = ctrl;
#endif
        }

        // 技能释放 → 触发释放动画
        if (SkillManager != null)
        {
            SkillManager.OnSkillCast += (_, _) =>
            {
                if (_animator != null && HasAnimatorParameter("IsCasting"))
                {
                    _animator.SetBool("IsCasting", true);
                    StartCoroutine(ResetCastBool(1.4f));
                }
            };
        }

        // ═══ 单一数据源：EnemyConfig → EnemyStats（全部属性） ═══
        if (config != null)
        {
            if (Health != null)
            {
                Health.MaxHealth             = config.maxHealth;
                Health.PatrolSpeed           = config.patrolSpeed;
                Health.ChaseSpeed            = config.chaseSpeed;
                Health.DetectionRange        = config.detectionRange;
                Health.AttackRange           = config.attackRange;
                Health.ContactDamage         = config.contactDamage;
                Health.ContactDamageCooldown = config.contactDamageCooldown;
                Health.Initialize();
            }

            if (SkillManager != null)
            {
                // 固定技能列表优先：按 ID 精确装配；否则从技能库随机抽取
                if (config.fixedSkillIds != null && config.fixedSkillIds.Count > 0)
                    SkillManager.LoadSkills(config.skillLibrary, config.fixedSkillIds.ToArray());
                else
                    SkillManager.InitializeFromLibrary(config.skillLibrary);

                // 被动技能（永久光环等）在装配后自动执行一次
                SkillManager.AutoCastPassives(this);
            }
        }
        else if (Health != null)
        {
            Health.Initialize();
        }

        // 绑定死亡事件
        if (Health != null)
        {
            Health.OnDied += () =>
            {
                OnDied?.Invoke();
                OnAnyEnemyDied?.Invoke(this);
                if (StateMachine != null)
                    StateMachine.ChangeState(new DeadState(this));
            };
        }
    }

    private void Start()
    {
        StartCoroutine(LazyFindPlayer());

        // 启动默认状态
        if (StateMachine != null)
        {
            if (config != null && config.patrolPoints != null && config.patrolPoints.Count > 0)
                StateMachine.ChangeState(new PatrolState(this));
            else
                StateMachine.ChangeState(new IdleState(this));
        }
    }

    private System.Collections.IEnumerator LazyFindPlayer()
    {
        while (PlayerTarget == null)
        {
            if (PlayerManager.Instance != null && PlayerManager.Instance.CurrentPlayer != null)
                PlayerTarget = PlayerManager.Instance.CurrentPlayer.transform;
            else
                PlayerTarget = GameObject.FindGameObjectWithTag("Player")?.transform;

            yield return new WaitForSeconds(0.3f);
        }
    }

    private System.Collections.IEnumerator ResetCastBool(float delay)
    {
        yield return new WaitForSeconds(delay);
        if (_animator != null && HasAnimatorParameter("IsCasting"))
            _animator.SetBool("IsCasting", false);
    }

    /// <summary>检查 Animator 是否包含指定参数（避免 SetBool 报 "Parameter does not exist"）</summary>
    private bool HasAnimatorParameter(string paramName)
    {
        if (_animator == null || _animator.parameters == null) return false;
        foreach (var p in _animator.parameters)
            if (p.name == paramName) return true;
        return false;
    }

    // ---------- 朝向 ----------
    private void LateUpdate()
    {
        if (IsDead || _spriteRenderer == null || PlayerTarget == null) return;

        // 施法期间也允许翻转，始终跟随玩家方向
        float dx = PlayerTarget.position.x - transform.position.x;
        if (Mathf.Abs(dx) > 0.1f)
            _spriteRenderer.flipX = dx < 0f;
    }

    // ---------- 碰撞伤害 ----------

    private void OnTriggerStay2D(Collider2D other)
    {
        ProcessContactDamage(other.gameObject);
    }

    private void OnCollisionStay2D(Collision2D collision)
    {
        ProcessContactDamage(collision.gameObject);
    }

    private void ProcessContactDamage(GameObject other)
    {
        if (IsDead || Health == null) return;

        string targetTag = IsAssimilated ? "Enemy" : "Player";
        if (!other.CompareTag(targetTag)) return;

        if (Time.time < _lastContactDamageTime + Health.ContactDamageCooldown) return;

        // 护盾拦截
        var shield = other.GetComponent<KeratinShieldRuntime>();
        if (shield != null && shield.IsActive)
        {
            shield.TryBlock();
            _lastContactDamageTime = Time.time;
            return;
        }

        // 碰撞免疫
        var playerStats = other.GetComponent<PlayerStats>();
        if (playerStats != null && playerStats.ImmuneToContactDamage) return;

        float dmg = Health.ContactDamage;

        // 细胞骨架：非随从（敌人）对玩家的碰撞伤害减免
        if (!IsAssimilated && PlayerCollisionReductionFactor < 1f)
            dmg *= PlayerCollisionReductionFactor;

        // 干扰素：随从攻击命中时给目标减速
        if (IsAssimilated && EnemyFollower.ApplySlow && other.CompareTag("Enemy"))
        {
            var slow = other.GetComponent<SlowEffect>();
            if (slow == null)
                slow = other.AddComponent<SlowEffect>();
            slow.Apply(EnemyFollower.SlowFactor, EnemyFollower.SlowDuration);
        }

        var damageable = other.GetComponent<IDamageable>();
        if (damageable != null)
        {
            damageable.TakeDamage(dmg);
            _lastContactDamageTime = Time.time;

            // 广播接触命中事件（供 OnContactHitBuff 等效果使用）
            OnAnyContactHit?.Invoke(this, other.gameObject);
        }
    }

    // ---------- IDamageable (门面) ----------
    public void TakeDamage(float damage)
    {
        if (Health != null)
            Health.TakeDamage(damage);
    }

    // ---------- ISkillCaster ----------
    public Transform CasterTransform => transform;

    public Vector2 GetTargetDirection()
    {
        if (PlayerTarget == null) return Vector2.down;
        return (PlayerTarget.position - transform.position).normalized;
    }

    public float GetAttackStrength()
    {
        return Health != null ? Health.ContactDamage : 10f;
    }

    public Projectile.OwnerType GetOwnerType() =>
        IsAssimilated ? Projectile.OwnerType.Player : Projectile.OwnerType.Enemy;

    public float GetSkillDamageModifier() => 1f;

    // ---------- 同化 ----------
    public void Assimilate(Transform playerTarget)
    {
        IsAssimilated = true;

        if (Health != null)
            Health.ClearOnDied();

        OnAssimilated?.Invoke(this);

        gameObject.tag = "Player";

        if (StateMachine != null)
            StateMachine.enabled = false;

        Movement?.Stop();

        EnemyFollower follower = GetComponent<EnemyFollower>();
        if (follower == null)
            follower = gameObject.AddComponent<EnemyFollower>();
        follower.Activate(playerTarget);

        PlayerTarget = playerTarget;
    }
}

using System.Collections.Generic;
using UnityEngine;
using UnityEngine.SceneManagement;

/// <summary>
/// 玩家管理器 (持久化单例) — 负责动态生成 Player 并跨场景保留。
///
/// 通过 [RuntimeInitializeOnLoadMethod] 在首个场景加载前自动创建，
/// 通过 SceneManager.sceneLoaded 事件在每次场景加载时检测：
/// - 场景中有 Player（Tag="Player"）→ 标记 DontDestroyOnLoad 保留
/// - 场景中无 Player → 从 Player 预制体动态生成
///
/// 依赖: 项目中存在 Tag="Player" 的 Player 预制体 (Assets/Prefab/Player.prefab)
/// 被 MapManager / EnemyCore 通过 GameObject.FindGameObjectWithTag("Player") 自动发现
/// </summary>
public class PlayerManager : MonoBehaviour
{
    public static PlayerManager Instance { get; private set; }

    [Header("Player 预制体")]
    [SerializeField] private GameObject _playerPrefab;

    [Header("出生位置")]
    [SerializeField] private Vector3 _spawnPosition = Vector3.zero;

    /// <summary>场景加载后触发: 参数为 (Player GameObject)</summary>
    public event System.Action<GameObject> OnPlayerReady;

    /// <summary>当前 Player GameObject 引用</summary>
    public GameObject CurrentPlayer { get; private set; }

    // ==================== 生命周期 ====================

    /// <summary>
    /// 在首个场景加载前自动创建 PlayerManager GameObject。
    /// 确保在任何场景加载时 PlayerManager 都已在 DontDestroyOnLoad 中就绪。
    /// </summary>
    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]
    private static void AutoInitialize()
    {
        if (Instance != null) return;

        var go = new GameObject("[PlayerManager]");
        go.AddComponent<PlayerManager>();
    }

    private void Awake()
    {
        if (Instance != null && Instance != this)
        {
            Destroy(gameObject);
            return;
        }
        Instance = this;
        DontDestroyOnLoad(gameObject);

        // Editor: 自动查找 Player 预制体，免去手动配置
        // Build: 需将 Player.prefab 放入 Resources/ 目录
        if (_playerPrefab == null)
        {
            _playerPrefab = ResolvePlayerPrefab();
        }
    }

    private void OnEnable()
    {
        SceneManager.sceneLoaded += OnSceneLoaded;
    }

    private void OnDisable()
    {
        SceneManager.sceneLoaded -= OnSceneLoaded;
    }

    // ==================== 场景加载回调 ====================

    /// <summary>每次场景加载后触发，确保场景中存在 Player</summary>
    private void OnSceneLoaded(Scene scene, LoadSceneMode mode)
    {
        // Start 场景: 销毁 Player 和统计数据
        if (scene.name == "Start")
        {
            if (CurrentPlayer != null)
            {
                Destroy(CurrentPlayer);
                CurrentPlayer = null;
            }
            DestroyStatistics();
            return;
        }

        // Result / Winning 结算场景: 销毁 Player，但保留统计数据供 UI 展示
        if (scene.name == "Result" || scene.name == "Winning")
        {
            if (CurrentPlayer != null)
            {
                Destroy(CurrentPlayer);
                CurrentPlayer = null;
            }
            return;
        }

        // === 游戏场景 ===

        // 确保 GameStatistics 存在
        if (GameStatistics.Instance == null)
        {
            var statsGo = new GameObject("[GameStatistics]");
            statsGo.AddComponent<GameStatistics>();
        }

        var player = GameObject.FindGameObjectWithTag("Player");

        // 已存在 Player —— 优先复用（可能是场景中手动放置的，或是上一场景保留的）
        if (player != null)
        {
            // 首次注册: 标记为 DontDestroyOnLoad 以便跨场景保留
            if (player != CurrentPlayer)
            {
                CurrentPlayer = player;
                DontDestroyOnLoad(player);

                // 跨场景复用时不保留当前位置，重置
                player.transform.position = Vector3.zero;

#if UNITY_EDITOR
                Debug.Log($"[PlayerManager] 复用场景中已有的 Player: '{player.name}', 位置={Vector3.zero}");
#endif
            }
            player.transform.position = Vector3.zero;
        }
        // 无 Player —— 从预制体动态生成
        else
        {
            if (_playerPrefab == null)
            {
                Debug.LogError("[PlayerManager] _playerPrefab 未配置！请在 Inspector 中指定 Player 预制体。");
                return;
            }

            var spawned = Instantiate(_playerPrefab, _spawnPosition, Quaternion.identity);
            spawned.name = "Player";
            DontDestroyOnLoad(spawned);
            CurrentPlayer = spawned;

            // 应用 PlayerConfig 基础值 + 科技树局外加成
            ApplyPlayerConfig(spawned);

#if UNITY_EDITOR
            Debug.Log($"[PlayerManager] 动态生成 Player，位置={spawned.transform.position}");
#endif
        }

        // 绑定 Player 到统计系统
        GameStatistics.Instance?.BindPlayer(CurrentPlayer);

        OnPlayerReady?.Invoke(CurrentPlayer);
    }

    /// <summary>销毁统计数据</summary>
    private static void DestroyStatistics()
    {
        if (GameStatistics.Instance != null)
        {
            if (Application.isPlaying)
                Destroy(GameStatistics.Instance.gameObject);
            else
                DestroyImmediate(GameStatistics.Instance.gameObject);
        }
    }

    // ==================== 辅助 ====================

    /// <summary>应用 PlayerConfig 基础值 + 科技树局外加成（仅在动态生成 Player 时调用）</summary>
    private void ApplyPlayerConfig(GameObject player)
    {
        if (player == null) return;

        var stats = player.GetComponent<PlayerStats>();
        if (stats == null) return;

        // 加载 PlayerConfig
        var config = Resources.Load<PlayerConfig>("PlayerConfig");
        if (config != null)
        {
            stats.ApplyBaseStats(config);
        }
        else
        {
            Debug.LogWarning("[PlayerManager] 未找到 PlayerConfig，Player 将使用预制体上的默认值。路径: Resources/PlayerConfig");
        }

                    // 叠加科技树加成
                    var mgr = TechTreeManager.Instance;
                    if (mgr != null)
                    {
                        var bonuses = mgr.GetAllBonuses();
                        if (bonuses != null && bonuses.Count > 0)
                        {
                            stats.ApplyBonuses(bonuses);
        #if UNITY_EDITOR
                            Debug.Log($"[PlayerManager] 已应用科技树加成: {bonuses.Count} 项");
        #endif
                        }

                        // 应用待执行的技能槽扩展
                        while (TechTreeMechanismEffect.ConsumePendingSkillSlotExpand())
                        {
                            var skillMgr = player.GetComponent<PlayerSkillManager>();
                            if (skillMgr != null)
                            {
                                skillMgr.ExpandSlots(1);
                                Debug.Log("[PlayerManager] 技能槽位 +1（科技树）");
                            }
                        }
                    }
    }

    /// <summary>自动查找 Player 预制体引用</summary>
    private static GameObject ResolvePlayerPrefab()
    {
#if UNITY_EDITOR
        // Editor 模式: 通过 AssetDatabase 按路径加载
        var prefab = UnityEditor.AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/Player.prefab");
        if (prefab != null)
        {
            Debug.Log("[PlayerManager] 已自动加载 Player 预制体: Assets/Prefab/Player.prefab");
            return prefab;
        }
        Debug.LogWarning("[PlayerManager] 未找到 Assets/Prefab/Player.prefab，请确认路径正确。");
#endif

        // Build 模式: 从 Resources 目录加载
        var resourcePrefab = Resources.Load<GameObject>("Player");
        if (resourcePrefab != null)
        {
            Debug.Log("[PlayerManager] 已从 Resources 加载 Player 预制体。");
            return resourcePrefab;
        }

        Debug.LogError(
            "[PlayerManager] 无法找到 Player 预制体！\n" +
            "  - Editor: 请确认 Assets/Prefab/Player.prefab 存在\n" +
            "  - Build: 请将 Player.prefab 放入任意 Resources/ 目录下");
        return null;
    }
}

using System;
using UnityEngine;

/// <summary>
/// 敌人统计数据组件 — 所有属性的唯一数据源（类似 PlayerStats）。
/// 血量、移速、感知范围、攻击范围、碰撞伤害等统一在此管理，
/// 提供 GetStatValue / SetStatValue 接口供 Buff 系统读写。
///
/// 数据初始化：EnemyCore 在 Awake 中从 EnemyConfig 赋值，然后调用 Initialize()。
/// </summary>
public class EnemyStats : MonoBehaviour, IDamageable, IHealable
{
    // ════════════════════════════════════════════
    //  生命
    // ════════════════════════════════════════════
    [Header("──── 生命 ────")]
    public float MaxHealth = 30f;
    private float _health;
    private bool _isDead = false;
    private bool _initialized = false;

    // ════════════════════════════════════════════
    //  移动速度
    // ════════════════════════════════════════════
    [Header("──── 移动速度 ────")]
    [Tooltip("巡逻速度")]
    public float PatrolSpeed = 1f;
    [Tooltip("追击速度")]
    public float ChaseSpeed = 2.5f;

    // ════════════════════════════════════════════
    //  感知与攻击
    // ════════════════════════════════════════════
    [Header("──── 感知与攻击 ────")]
    [Tooltip("发现玩家范围")]
    public float DetectionRange = 5f;
    [Tooltip("攻击范围")]
    public float AttackRange = 1.2f;

    // ════════════════════════════════════════════
    //  碰撞伤害
    // ════════════════════════════════════════════
    [Header("──── 碰撞伤害 ────")]
    [Tooltip("接触玩家时造成的伤害")]
    public float ContactDamage = 10f;
    [Tooltip("碰撞伤害冷却（秒）")]
    public float ContactDamageCooldown = 1f;

    // ──────────────────────────────────────────
    //  只读属性
    // ──────────────────────────────────────────
    public bool IsDead => _isDead;
    public float CurrentHealth => _health;

    // ──────────────────────────────────────────
    //  事件
    // ──────────────────────────────────────────
    public event Action<float, float> OnHealthChanged;
    public event Action OnDied;
    public event Action<float> OnDamaged;
    /// <summary>属性变化事件：参数为 (属性名)</summary>
    public event Action<string> OnStatChanged;

    /// <summary>技能命中附带目标当前生命的百分比伤害（蛋白激酶），0=关闭</summary>
    public static float OnSkillHitPercentDamage = 0f;

    // ──────────────────────────────────────────
    //  初始化
    // ──────────────────────────────────────────

    /// <summary>
    /// 由 EnemyCore 在设置各项属性后调用。
    /// 确保 _health 从最终 MaxHealth 初始化。
    /// </summary>
    public void Initialize()
    {
        if (_initialized) return;
        _health = MaxHealth;
        _initialized = true;
    }

    // ──────────────────────────────────────────
    //  IDamageable
    // ──────────────────────────────────────────

    public void TakeDamage(float damage)
    {
        if (_isDead) return;

        var immunity = GetComponent<DamageImmunity>();
        if (immunity != null && immunity.IsImmune) return;

        // 受击闪避（肌纤维应激细胞等）：成功闪避则免疫本次伤害并滑移
        var dodge = GetComponent<DodgeComponent>();
        if (dodge != null)
        {
            // 闪避方向：远离最近的敌人（通常是玩家/攻击者方向的反向）
            Vector2 hitDir = Vector2.right;
            var player = PlayerManager.Instance != null ? PlayerManager.Instance.CurrentPlayer : null;
            if (player != null)
                hitDir = ((Vector2)transform.position - (Vector2)player.transform.position).normalized;
            if (hitDir.sqrMagnitude < 0.01f)
                hitDir = Vector2.right;

            if (dodge.TryDodge(hitDir))
                return;  // 闪避成功，免疫本次伤害
        }

        // 伤害吸收护盾（角质增厚细胞等）：先免伤再吸收
        var absorbShield = GetComponent<AbsorbShield>();
        if (absorbShield != null && absorbShield.IsActive)
            absorbShield.TryAbsorb(ref damage);

        if (damage <= 0f) return;

        var analgesic = GetComponent<AnalgesicBlockRuntime>();
        if (analgesic != null && analgesic.IsActive)
            damage = analgesic.SplitDamage(damage);

        // 蛋白激酶：技能命中附带目标当前生命百分比伤害
        if (SkillInstance.SkillDamageActive && OnSkillHitPercentDamage > 0f)
            damage += _health * OnSkillHitPercentDamage;

        _health -= damage;
        _health = Mathf.Max(_health, 0f);

        DamagePopup.Spawn(transform.position, damage);

        if (CameraShake.Instance != null)
            CameraShake.Instance.Shake(0.7f);

        OnDamaged?.Invoke(damage);
        OnHealthChanged?.Invoke(_health, MaxHealth);

        if (_health <= 0f)
            Die();
    }

    // ──────────────────────────────────────────
    //  IHealable
    // ──────────────────────────────────────────

    public void Heal(float amount)
    {
        if (_isDead) return;
        _health = Mathf.Min(_health + amount, MaxHealth);
        OnHealthChanged?.Invoke(_health, MaxHealth);
    }

    private void Die()
    {
        if (_isDead) return;
        _isDead = true;
        OnDied?.Invoke();
    }

    /// <summary>清除 OnDied 事件的所有订阅者（同化时切换死亡处理）。</summary>
    public void ClearOnDied()
    {
        OnDied = null;
    }

    // ──────────────────────────────────────────
    //  Buff 系统属性读写接口（类同 PlayerStats）
    // ──────────────────────────────────────────

    public float GetStatValue(string statName)
    {
        return statName switch
        {
            "MaxHealth"             => MaxHealth,
            "Health"                => _health,
            "PatrolSpeed"           => PatrolSpeed,
            "ChaseSpeed"            => ChaseSpeed,
            "DetectionRange"        => DetectionRange,
            "AttackRange"           => AttackRange,
            "ContactDamage"         => ContactDamage,
            "ContactDamageCooldown" => ContactDamageCooldown,
            _ => throw new ArgumentException($"EnemyStats: 未知属性名 '{statName}'")
        };
    }

    public void SetStatValue(string statName, float value)
    {
        switch (statName)
        {
            case "MaxHealth":
                MaxHealth = Mathf.Max(value, 1f);
                _health = Mathf.Min(_health, MaxHealth);
                break;
            case "Health":
                _health = Mathf.Clamp(value, 0f, MaxHealth);
                break;
            case "PatrolSpeed":
                PatrolSpeed = Mathf.Max(value, 0f);
                break;
            case "ChaseSpeed":
                ChaseSpeed = Mathf.Max(value, 0f);
                break;
            case "DetectionRange":
                DetectionRange = Mathf.Max(value, 0f);
                break;
            case "AttackRange":
                AttackRange = Mathf.Max(value, 0f);
                break;
            case "ContactDamage":
                ContactDamage = Mathf.Max(value, 0f);
                break;
            case "ContactDamageCooldown":
                ContactDamageCooldown = Mathf.Max(value, 0f);
                break;
            default:
                throw new ArgumentException($"EnemyStats: 未知属性名 '{statName}'");
        }
        OnStatChanged?.Invoke(statName);
    }
}

using UnityEngine;

/// <summary>
/// 怪物生成器 — 可独立使用或挂载在房间上
/// 负责从配置中读取怪物池并按权重生成敌人
/// </summary>
public class EnemySpawner : MonoBehaviour
{
    [Header("生成配置")]
    [Tooltip("引用房间配置 (为空则使用下方手动配置)")]
    public RoomConfig roomConfig;

    [Tooltip("手动配置 — 仅在没有 roomConfig 时使用")]
    public EnemySpawnEntry[] manualEntries;
    public int manualMinEnemies = 1;
    public int manualMaxEnemies = 3;

    [Header("生成点")]
    public Transform[] spawnPoints;

    /// <summary>存活怪物追踪</summary>
    public event System.Action OnAllEnemiesDefeated;

    private int _aliveCount;
    private bool _hasSpawned;
    private bool _defeatCheckPending;

    /// <summary>开始生成</summary>
    public void Spawn()
    {
        if (_hasSpawned) return;
        _hasSpawned = true;

        var entries = roomConfig != null ? roomConfig.enemyPool : 
            (manualEntries != null ? new System.Collections.Generic.List<EnemySpawnEntry>(manualEntries) : null);

        if (entries == null || entries.Count == 0) return;

        int min = roomConfig != null ? roomConfig.minEnemies : manualMinEnemies;
        int max = roomConfig != null ? roomConfig.maxEnemies : manualMaxEnemies;
        int total = Random.Range(min, max + 1);
        int available = spawnPoints != null ? spawnPoints.Length : 0;
        if (available == 0) return;

        int count = Mathf.Min(total, available);

        // 洗牌生成点
        var indices = new int[available];
        for (int i = 0; i < available; i++) indices[i] = i;
        for (int i = indices.Length - 1; i > 0; i--)
        {
            int j = Random.Range(0, i + 1);
            (indices[i], indices[j]) = (indices[j], indices[i]);
        }

        for (int i = 0; i < count; i++)
        {
            var entry = PickWeighted(entries);
            if (entry == null || entry.enemyPrefab == null) continue;

            var point = spawnPoints[indices[i]];
            var enemy = Instantiate(entry.enemyPrefab, point.position, Quaternion.identity, transform);

            RegisterEnemy(enemy);
        }
    }

    /// <summary>
    /// 注册一个敌人到房间计数，并监听其死亡/同化事件。
    /// 生成器直接生成的敌人与亡语（死亡分裂）爆出的敌人都通过此方法计数，
    /// 否则亡语怪不计入计数会导致房间门提前开启。
    /// 同时转发到 RoomManager（真正的门锁控制者）的 _aliveEnemies。
    /// </summary>
    public void RegisterEnemy(GameObject enemy)
    {
        if (enemy == null) return;

        _aliveCount++;
        _defeatCheckPending = false;  // 新敌人注册，取消 pending 的开门检查

        // 转发到 RoomManager（门锁由 RoomManager._aliveEnemies 控制）
        var room = GetComponentInParent<RoomManager>();
        if (room != null)
            room.RegisterEnemy(enemy);

        // 监听死亡和同化（使用 IEnemy 接口以便兼容重构后的敌人）
        if (enemy.TryGetComponent<IEnemy>(out var ienemy))
        {
            ienemy.OnDied += () =>
            {
                _aliveCount--;
                TryDefeat();
            };
            ienemy.OnAssimilated += (_) =>
            {
                _aliveCount--;
                TryDefeat();
            };
        }
    }

    /// <summary>
    /// 检查是否所有敌人都已击败。延迟到下一帧执行，
    /// 给亡语（OnDied 事件链里的 Instantiate + RegisterEnemy）留出执行时间。
    /// 若延迟期间有新敌人注册（亡语生成），则取消开门。
    /// </summary>
    private void TryDefeat()
    {
        if (_aliveCount > 0) return;
        if (_defeatCheckPending) return;

        _defeatCheckPending = true;
        StartCoroutine(DeferredDefeatCheck());
    }

    private System.Collections.IEnumerator DeferredDefeatCheck()
    {
        // 等一帧，让同一帧内其他 OnDied 订阅者（亡语 buff）执行完毕
        yield return null;

        // 期间有新敌人注册 → 取消开门（_defeatCheckPending 已被 RegisterEnemy 清 false）
        if (!_defeatCheckPending)
            yield break;

        _defeatCheckPending = false;

        if (_aliveCount <= 0)
            OnAllEnemiesDefeated?.Invoke();
    }

    private EnemySpawnEntry PickWeighted(System.Collections.Generic.List<EnemySpawnEntry> entries)
    {
        float total = 0f;
        foreach (var e in entries) total += e.weight;
        if (total <= 0f) return entries[0];

        float roll = Random.Range(0f, total);
        float cumulative = 0f;
        foreach (var e in entries)
        {
            cumulative += e.weight;
            if (roll <= cumulative) return e;
        }
        return entries[^1];
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 地图管理器 (单例) — 新地图系统的核心管理器。
/// 替代旧的 TileManager。
/// 负责: 地图生成、房间实例化、房间切换、玩家追踪。
/// </summary>
public class MapManager : MonoBehaviour
{
    public static MapManager Instance { get; private set; }

    [Header("地图配置")]
    [SerializeField] private MapConfig _mapConfig;

    [Header("运行时")]
    [SerializeField] private int _currentRoomId;
    [SerializeField] private bool _isSwitchingRoom;

    // 内部状态
    private RoomGraph _roomGraph;
    private MapGenerator _generator;
    private Dictionary<int, RoomRoot> _roomInstances = new();
    private RoomRoot _currentRoom;
    private Coroutine _switchCoroutine;
    private Transform _playerTransform;

    /// <summary>玩家从门进入新房间时的内缩距离 (避免立刻再次触发门)</summary>
    [SerializeField] private float _doorEntryOffset = 0f;

    // 事件
    public event System.Action<int, int> OnRoomChanged; // (fromRoomId, toRoomId)
    public event System.Action<int, int> OnRoomSwitchStarted;
    public event System.Action<int> OnRoomSwitchCompleted; // (newRoomId)

    // 属性
    public RoomRoot CurrentRoom => _currentRoom;
    public int CurrentRoomId => _currentRoomId;
    public bool IsSwitchingRoom => _isSwitchingRoom;
    public RoomGraph RoomGraph => _roomGraph;
    public MapConfig MapConfigAsset => _mapConfig;

    private void Awake()
    {
        if (Instance != null && Instance != this)
        {
            Destroy(gameObject);
            return;
        }
        Instance = this;
    }

    private void Start()
    {
        // 缓存玩家 Transform
        var playerGo = GameObject.FindGameObjectWithTag("Player");
        if (playerGo != null)
            _playerTransform = playerGo.transform;

        if (_mapConfig != null)
        {
            GenerateMap();
        }
        else
        {
            Debug.LogError("MapManager: MapConfig 未配置!");
        }
    }

    // ==================== 地图生成 ====================

    /// <summary>生成并实例化地图</summary>
    public void GenerateMap()
    {
        if (_mapConfig == null)
        {
            Debug.LogError("MapManager: MapConfig 为空，无法生成地图");
            return;
        }

        // 清理旧实例
        ClearExistingRooms();

        // 设置随机种子
        int seed = _mapConfig.useRandomSeed ? Random.Range(0, int.MaxValue) : _mapConfig.seed;

        // 生成房间图
        _generator = new MapGenerator(_mapConfig);
        _roomGraph = _generator.Generate(seed);

        // 实例化所有房间
        foreach (var node in _roomGraph.nodes)
        {
            InstantiateRoom(node);
        }

        // 设置所有 RoomPortal 的目标房间
        SetupPortals();

        // 先隐藏所有房间
        foreach (var room in _roomInstances.Values)
        {
            room.Deactivate();
        }

        // 激活起始房间
        var startNode = _roomGraph.GetNode(_roomGraph.startRoomId);
        if (startNode != null && _roomInstances.TryGetValue(_roomGraph.startRoomId, out var startRoom))
        {
            startRoom.Activate();
            _currentRoomId = startRoom.roomId;
            _currentRoom = startRoom;

            // 通知 RoomManager 玩家进入
            var roomMgr = startRoom.GetComponent<RoomManager>();
            if (roomMgr != null)
                roomMgr.OnPlayerEnter();
        }

        Debug.Log($"MapManager: 地图生成完成 — {_roomGraph.nodes.Count} 个房间, Start={_roomGraph.startRoomId}");
    }

    /// <summary>实例化单个房间</summary>
    private void InstantiateRoom(RoomNode node)
    {
        var prefab = node.config.GetRandomPrefab();
        if (prefab == null)
        {
            Debug.LogError($"MapManager: RoomConfig '{node.config.name}' 没有预制体!");
            return;
        }

        var go = Instantiate(prefab, node.worldPosition, Quaternion.identity, transform);
        go.name = $"Room_{node.roomId}_{node.roomType}";

        var root = go.GetComponent<RoomRoot>();
        if (root == null)
        {
            root = go.AddComponent<RoomRoot>();
        }

        root.config = node.config;
        root.roomId = node.roomId;

        // 确保有 RoomManager
        var roomMgr = go.GetComponent<RoomManager>();
        if (roomMgr == null)
            go.AddComponent<RoomManager>();

        _roomInstances[node.roomId] = root;
    }

    /// <summary>设置所有门的连接目标；无连接的门伪装为墙壁。</summary>
    private void SetupPortals()
    {
        foreach (var node in _roomGraph.nodes)
        {
            if (!_roomInstances.TryGetValue(node.roomId, out var root))
                continue;

            var portals = root.GetComponentsInChildren<RoomPortal>(true);
            foreach (var portal in portals)
            {
                // 查找匹配的连接
                bool connected = false;
                foreach (var conn in node.connections)
                {
                    if (conn.Value == portal.direction)
                    {
                        portal.targetRoomId = conn.Key;

                        // 如果目标房间是隐藏房，设置为可破坏墙壁
                        var targetNode = _roomGraph.GetNode(conn.Key);
                        if (targetNode != null && targetNode.roomType == RoomType.Hidden)
                        {
                            int hp = targetNode.config.hiddenWallHP > 0 ? targetNode.config.hiddenWallHP : 4;
                            portal.SetAsBreakableWall(hp);
                        }

                        connected = true;
                        break;
                    }
                }

                if (!connected)
                {
                    portal.HideAsWall();
                }
            }
        }
    }

    // ==================== 房间切换 ====================

    /// <summary>切换到目标房间，玩家从指定方向的门进入</summary>
    public void SwitchRoom(int targetRoomId, DoorDirection entryDir)
    {
        if (_isSwitchingRoom) return;
        if (targetRoomId == _currentRoomId) return;
        if (!_roomInstances.TryGetValue(targetRoomId, out var targetRoom)) return;

        StartCoroutine(SwitchRoomRoutine(targetRoomId, targetRoom, entryDir));
    }

    private IEnumerator SwitchRoomRoutine(int targetRoomId, RoomRoot targetRoom, DoorDirection entryDir)
    {
        _isSwitchingRoom = true;
        int fromRoomId = _currentRoomId;

        OnRoomSwitchStarted?.Invoke(fromRoomId, targetRoomId);

        // 通知旧房间玩家离开
        if (_currentRoom != null)
        {
            var oldMgr = _currentRoom.GetComponent<RoomManager>();
            oldMgr?.OnPlayerExit();
        }

        // 激活新房间
        targetRoom.Activate();

        // 传送玩家到目标房间入口 (反方向门的内侧)
        DoorDirection targetEntryDir = RoomConfig.OppositeDir(entryDir);
        TeleportPlayerToDoor(targetRoom, targetEntryDir);

        // 通知新房间玩家进入
        var newMgr = targetRoom.GetComponent<RoomManager>();
        newMgr?.OnPlayerEnter();

        // 更新状态
        _currentRoom = targetRoom;
        _currentRoomId = targetRoomId;

        // 等待摄像机过渡完成
        var cameraCtrl = Camera.main != null ? Camera.main.GetComponent<RoomCameraController>() : null;
        if (cameraCtrl != null)
        {
            bool transitionDone = false;
            cameraCtrl.MoveToRoom(targetRoom, () => transitionDone = true);
            yield return new WaitUntil(() => transitionDone);
        }

        // 隐藏旧房间
        foreach (var kvp in _roomInstances)
        {
            if (kvp.Key != _currentRoomId)
                kvp.Value.Deactivate();
        }

        _isSwitchingRoom = false;
        OnRoomChanged?.Invoke(fromRoomId, targetRoomId);
        OnRoomSwitchCompleted?.Invoke(targetRoomId);

        // 统计：访问房间已由 RoomManager.OnPlayerEnter（_isFirstEnter 守卫）负责，此处不再重复

        Debug.Log($"MapManager: 切换到房间 {targetRoomId} ({targetRoom.config.roomType})");
    }

    /// <summary>将玩家传送到目标房间入口门内侧的地板中央位置</summary>
    private void TeleportPlayerToDoor(RoomRoot room, DoorDirection entryDir)
    {
        if (_playerTransform == null)
        {
            var playerGo = GameObject.FindGameObjectWithTag("Player");
            if (playerGo != null) _playerTransform = playerGo.transform;
        }
        if (_playerTransform == null) return;

        // 玩家从 entryDir 方向的门进入，放置在距离墙壁 _doorEntryOffset 格的位置
        Vector2 halfSize = room.roomSize * 0.5f;
        float offset = halfSize.y - _doorEntryOffset;
        if (entryDir is DoorDirection.Left or DoorDirection.Right)
            offset = halfSize.x - _doorEntryOffset;

        // 玩家从 entryDir 方向的门进入，放置在房间中心朝入口门方向偏移
        Vector2 doorDir = entryDir switch
        {
            DoorDirection.Top => Vector2.up,
            DoorDirection.Bottom => Vector2.down,
            DoorDirection.Left => Vector2.left,
            DoorDirection.Right => Vector2.right,
            _ => Vector2.zero
        };

        Vector2 targetPos = room.Center + doorDir * offset;

        TeleportRigidbody(_playerTransform, targetPos);
        TeleportFollowers(targetPos, doorDir, room.transform);
    }

    /// <summary>安全传送 Transform（优先通过 Rigidbody2D.position）</summary>
    private static void TeleportRigidbody(Transform t, Vector2 targetPos)
    {
        if (t == null) return;
        var rb = t.GetComponent<Rigidbody2D>();
        if (rb != null)
        {
            rb.velocity = Vector2.zero;
            rb.position = targetPos;
        }
        else
        {
            t.position = targetPos;
        }
    }

    /// <summary>将所有活跃随从传送到玩家两侧和侧前方（正前方留空不挡路），阵型跟随面朝方向旋转</summary>
    private static void TeleportFollowers(Vector2 playerPos, Vector2 playerForward, Transform newParent)
    {
        var followers = EnemyFollower.ActiveFollowers;
        int count = followers.Count;
        if (count == 0) return;

        float angle = Mathf.Atan2(playerForward.y, playerForward.x) - Mathf.PI / 2f;
        float cos = Mathf.Cos(angle);
        float sin = Mathf.Sin(angle);

        float halfPi = Mathf.PI / 2f;
        float gapAngle = 0.25f; // 正前方留空约 14°，不挡玩家视线和移动

        for (int i = 0; i < count; i++)
        {
            float t = count > 1 ? (float)i / (count - 1) : -0.5f;

            // 在 -90°~90° 之间分布，但跳过正前方 ±gap 区域
            float rad;
            if (count == 1)
            {
                rad = -halfPi + gapAngle; // 单个随从放左侧
            }
            else if (t <= 0.5f)
            {
                rad = Mathf.Lerp(-halfPi, -gapAngle, t * 2f);   // 左侧到左前方
            }
            else
            {
                rad = Mathf.Lerp(gapAngle, halfPi, (t - 0.5f) * 2f); // 右前方到右侧
            }

            float sideX = Mathf.Sin(rad);
            float forwardY = Mathf.Cos(rad);
            Vector2 localOffset = new Vector2(sideX, forwardY) * 1.2f;

            Vector2 rotatedOffset = new Vector2(
                localOffset.x * cos - localOffset.y * sin,
                localOffset.x * sin + localOffset.y * cos
            );

            Vector2 targetPos = playerPos + rotatedOffset;
            followers[i].transform.SetParent(newParent, true);
            TeleportRigidbody(followers[i].transform, targetPos);
        }
    }

    // ==================== 查询 API ====================

    /// <summary>根据 ID 获取房间</summary>
    public RoomRoot GetRoom(int roomId)
    {
        _roomInstances.TryGetValue(roomId, out var room);
        return room;
    }

    /// <summary>获取相邻房间列表</summary>
    public List<RoomRoot> GetAdjacentRooms(int roomId)
    {
        var result = new List<RoomRoot>();
        var node = _roomGraph?.GetNode(roomId);
        if (node == null) return result;

        foreach (var conn in node.connections)
        {
            if (_roomInstances.TryGetValue(conn.Key, out var room))
                result.Add(room);
        }
        return result;
    }

    /// <summary>确保所有门的连接正确 (在编辑器修改后调用)</summary>
    public void RefreshPortals()
    {
        SetupPortals();
    }

    // ==================== 辅助 ====================

    private void ClearExistingRooms()
    {
        // 1. 清理已追踪的房间
        foreach (var kvp in _roomInstances)
        {
            if (kvp.Value != null)
                DestroyImmediate(kvp.Value.gameObject);
        }
        _roomInstances.Clear();

        // 2. 清理残余子物体 (场景中保存的旧房间)
        for (int i = transform.childCount - 1; i >= 0; i--)
        {
            var child = transform.GetChild(i).gameObject;
            if (child.GetComponent<RoomRoot>() != null)
                DestroyImmediate(child);
        }

        _roomGraph = null;
        _currentRoom = null;
    }

    /// <summary>在编辑器中重新生成 (通过 Context Menu 调用)</summary>
    [ContextMenu("Regenerate Map")]
    public void RegenerateMap()
    {
        ClearExistingRooms();
        GenerateMap();
    }
}

using UnityEngine;

/// <summary>
/// 移动组件：封装 Rigidbody2D 操作与视线检测缓存。
///
/// 速度数据源：EnemyStats.PatrolSpeed / EnemyStats.ChaseSpeed
///             由状态机在调用 MoveTowardsPosition 时显式传入。
/// </summary>
[RequireComponent(typeof(Rigidbody2D))]
public class EnemyMovement : MonoBehaviour
{
    [Tooltip("全局敌人速度倍率（道具效果），1=正常，0.5=半速")]
    public static float GlobalSpeedMultiplier = 1f;

    private Rigidbody2D _rb;
    private float _nextSightCheckTime;
    private bool _cachedHasLineOfSight;
    private bool _wasInDetectionRange = false;

    private void Awake()
    {
        _rb = GetComponent<Rigidbody2D>();
        if (_rb != null) _rb.freezeRotation = true;
    }

    public void Stop()
    {
        if (_rb != null) _rb.velocity = Vector2.zero;
    }

    /// <summary>
    /// 向目标位置移动。
    /// </summary>
    /// <param name="target">目标世界坐标</param>
    /// <param name="speed">移动速度</param>
    /// <param name="speedMultiplier">额外速度倍率（0~1），用于搜索等减速行为</param>
    public void MoveTowardsPosition(Vector2 target, float speed, float speedMultiplier = 1f)
    {
        if (_rb == null || speed <= 0f) return;
        Vector2 dir = (target - (Vector2)transform.position).normalized;
        _rb.velocity = dir * speed * speedMultiplier * GlobalSpeedMultiplier;
    }

    public void SetVelocity(Vector2 vel)
    {
        if (_rb == null) return;
        _rb.velocity = vel * GlobalSpeedMultiplier;
    }

    /// <summary>直接传送到目标位置</summary>
    public void Teleport(Vector2 targetPos)
    {
        if (_rb != null)
        {
            _rb.velocity = Vector2.zero;
            _rb.position = targetPos;
        }
        else
        {
            transform.position = targetPos;
        }
    }

    /// <summary>
    /// 带缓存的视线检测。
    /// </summary>
    public bool HasLineOfSight(Vector2 targetPosition, float detectionRange, float sightCheckInterval = 0.2f)
    {
        float sqrDistance = ((Vector2)transform.position - targetPosition).sqrMagnitude;
        bool inRange = sqrDistance <= detectionRange * detectionRange;

        if (!inRange)
        {
            _wasInDetectionRange = false;
            _cachedHasLineOfSight = false;
            return false;
        }

        if (!_wasInDetectionRange)
        {
            _nextSightCheckTime = 0f;
            _wasInDetectionRange = true;
        }

        if (Time.time >= _nextSightCheckTime)
        {
            _nextSightCheckTime = Time.time + sightCheckInterval;
            RaycastHit2D hit = Physics2D.Linecast(transform.position, targetPosition);
            _cachedHasLineOfSight = hit.collider == null || !hit.collider.CompareTag("Wall");
        }

        return _cachedHasLineOfSight;
    }
}

